// main.js - Adds region filter to dynamically show chart data
document.addEventListener("DOMContentLoaded", () => {
  const regionSelect = document.getElementById("regionSelect");
  const chartCanvas = document.getElementById("regionChart");

  if (regionSelect && chartCanvas) {
    regionSelect.addEventListener("change", () => {
      const selected = regionSelect.value;
      const allBars = Chart.instances[0]; // get first chart instance

      if (selected === "all") {
        allBars.data.datasets[0].data = window.regionData;
        allBars.data.labels = window.regionLabels;
      } else {
        const index = window.regionLabels.indexOf(selected);
        allBars.data.datasets[0].data = [window.regionData[index]];
        allBars.data.labels = [selected];
      }
      allBars.update();
    });
  }
});
